// Guards static/third-party-notices.txt (the "Open-source licenses" screen, #57).
//
// The file is generated by tools/third-party-notices.mjs from the lockfiles and the release APK.
// This test needs no network, no APK and no node_modules: it fails when someone adds or bumps a
// Rust crate or an npm package without regenerating the file. The release-apk test checks the
// Android libraries against a real APK.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { brandFontComponents, directDependencyVersions, npmPackageList } from "../../tools/third-party-notices.mjs";

const read = (rel) => readFileSync(new URL(`../../${rel}`, import.meta.url), "utf8");
const notices = read("static/third-party-notices.txt");
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/** True when the notices list `name version` as a component line (an optional " *" marker follows). */
const listed = (name, version) => new RegExp(`^${escape(name)} ${escape(version)}(?: \\*)? - `, "m").test(notices);

test("the notices file starts with its header and says what it is", () => {
  // assert.ok, not assert.match: a failed match would print the whole multi-megabyte file.
  const has = (re) => assert.ok(re.test(notices), `the notices file does not match ${re}`);
  assert.ok(notices.startsWith("OPENJOT THIRD-PARTY NOTICES\n"));
  has(/MIT License/);
  has(/Google ML Kit[\s\S]*?NOT\s+open\s+source/);
  has(/node tools\/third-party-notices\.mjs --apk/);
});

test("the OpenJot entry has the app's own version", () => {
  const { version } = JSON.parse(read("package.json"));
  assert.ok(listed("OpenJot", version), `the notices list a different OpenJot version than ${version}: regenerate them`);
});

test("every Rust crate in Cargo.lock is listed with its locked version", () => {
  const lock = read("src-tauri/Cargo.lock");
  const crates = [];
  for (const block of lock.split("[[package]]").slice(1)) {
    const name = /^name = "(.*)"$/m.exec(block)?.[1];
    const version = /^version = "(.*)"$/m.exec(block)?.[1];
    // The workspace's own crate (moojot) has no `source`.
    if (name && version && /^source = /m.test(block)) crates.push([name, version]);
  }
  assert.ok(crates.length > 100, "Cargo.lock parsing found too few crates");
  const missing = crates.filter(([name, version]) => !listed(name, version)).map(([n, v]) => `${n} ${v}`);
  assert.deepEqual(missing, [], "regenerate the notices: node tools/third-party-notices.mjs --apk <release apk>");
});

test("every production dependency in package.json is listed with its locked version", () => {
  const declared = Object.keys(JSON.parse(read("package.json")).dependencies);
  const resolved = directDependencyVersions();
  assert.deepEqual(Object.keys(resolved).sort(), [...declared].sort(), "package.json and bun.lock disagree");
  const missing = declared.filter((name) => !listed(name, resolved[name]));
  assert.deepEqual(missing.map((n) => `${n} ${resolved[n]}`), [], "regenerate the notices: node tools/third-party-notices.mjs --apk <release apk>");
});

test("every transitive production package and bundled build tool is listed too", () => {
  const { packages } = npmPackageList();
  assert.ok(packages.some((p) => p.name === "svelte") && packages.some((p) => p.name === "@sveltejs/kit"));
  const missing = packages.filter((p) => !listed(p.name, p.version)).map((p) => `${p.name} ${p.version}`);
  assert.deepEqual(missing, [], "regenerate the notices: node tools/third-party-notices.mjs --apk <release apk>");
});

test("the Android libraries the app declares are listed", () => {
  const gradle = read("src-tauri/gen/android/app/build.gradle.kts");
  const direct = [...gradle.matchAll(/^\s*implementation\("([^":]+):([^":]+):[^"]+"\)/gm)].map((m) => `${m[1]}:${m[2]}`);
  assert.ok(direct.length >= 8, "found too few implementation() dependencies in build.gradle.kts");
  const missing = direct.filter((coordinate) => !new RegExp(`^${escape(coordinate)} \\S+(?: \\*)? - `, "m").test(notices));
  assert.deepEqual(missing, [], "regenerate the notices: node tools/third-party-notices.mjs --apk <release apk>");
});

test("the model, the font and the native runtime have notices", () => {
  const has = (re) => assert.ok(re.test(notices), `the notices file does not match ${re}`);
  has(/Remtir\/AksonOCR-Lite/);
  has(/^@fontsource\/noto-sans-thai \S+ - OFL-1\.1/m);
  has(/ONNX Runtime native libraries/);
  has(/SIL OPEN FONT LICENSE/);
});

test("every brand font the app bundles is listed with the OFL-1.1 licence", () => {
  // Inter comes from @trajectonomics/brand/current/fonts/inter.css and Azeret Mono is copied
  // into static/fonts/; both are under the SIL Open Font License 1.1. The generator reads them
  // from the workspace, not from a registry, so this guards the committed file against drift.
  const fonts = brandFontComponents();
  const staticFonts = readdirSync(new URL("../../static/fonts/", import.meta.url)).filter((name) => name.endsWith(".woff2"));
  assert.ok(staticFonts.length > 0, "static/fonts/ has no woff2 file");
  const covered = new Set(fonts.flatMap((font) => font.name.match(/[\w.-]+\.woff2/g) ?? []));
  const expected = ["inter-latin-wght.woff2", "inter-latin-ext-wght.woff2", ...staticFonts];
  assert.deepEqual(expected.filter((file) => !covered.has(file)), [], "a brand font the app bundles has no notice");
  for (const font of fonts) {
    assert.equal(font.license, "OFL-1.1", `${font.name} is not listed as OFL-1.1`);
    assert.ok(
      new RegExp(`^${escape(font.name)} ${escape(font.version)}(?: \\*)? - OFL-1\\.1 \\[L\\d+\\]$`, "m").test(notices),
      `${font.name} is not listed in the notices: regenerate them with node tools/third-party-notices.mjs --apk <apk>`,
    );
    // The full licence text ships with each family, copyright line included. It is printed
    // verbatim because the OFL body itself contains lines that start with "Copyright".
    const text = font.texts[0].text.replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").replace(/[ \t]+$/gm, "").trim();
    assert.ok(notices.includes(text), `the notices do not reproduce the ${font.name} licence text in full`);
  }
});
